export function coverageFor(townId,nodes){return (rows[townId]||[]).map(([topic,ids,interactive])=>{const resources=ids.map(id=>nodes.find(n=>n.id===id));const modeled=ids.length>0&&resources.every(Boolean);return {topic,ids,modeled,explained:modeled&&resources.every(n=>Boolean(n.purpose&&n.notes)),interactive:modeled&&interactive,planned:!modeled||!interactive};});}
export function coverageTowns(){return Object.keys(rows);}
